#![forbid(unsafe_code)]
//! Checked byte spans and a bounded, resettable arena for the owned Rust port.
//!
//! Arena storage is owned by aligned blocks. Handles are offsets into chunks,
//! never pointers, so moving an arena does not invalidate them and Rust borrows
//! prevent access while the arena is being changed.

use std::sync::atomic::{AtomicU64, Ordering};

mod work_control;
pub use work_control::{BudgetControl, ControlledError, ControlledStep, Stop, WorkControl, WorkKind, WorkLimits, WorkStats};

#[cfg(not(all(target_os = "macos", target_arch = "aarch64")))]
compile_error!("Vexel initially supports Apple Silicon macOS 13+ only");

/// Error outcomes corresponding to the non-success C `base_status` values.
/// Success is represented by `Ok(…)` in Rust.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BaseStatus {
    Invalid,
    Overflow,
    Limit,
    OutOfMemory,
}

/// A checked half-open range into source bytes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    /// Create a span from an offset and length, returning `None` on overflow.
    pub fn from_offset_length(offset: usize, length: usize) -> Option<Self> {
        Some(Self {
            start: offset,
            end: offset.checked_add(length)?,
        })
    }

    /// Borrow this span from `source` if both endpoints are in bounds.
    pub fn slice(self, source: &[u8]) -> Option<&[u8]> {
        source.get(self.start..self.end)
    }
}

/// Return `a + b`, or `None` if the result cannot fit in `usize`.
pub fn size_add(a: usize, b: usize) -> Option<usize> {
    a.checked_add(b)
}

/// Return `a * b`, or `None` if the result cannot fit in `usize`.
pub fn size_mul(a: usize, b: usize) -> Option<usize> {
    a.checked_mul(b)
}

/// Borrowed immutable byte slice; empty slices may naturally have no address.
pub type Bytes<'a> = &'a [u8];
/// Borrowed mutable byte slice.
pub type MutBytes<'a> = &'a mut [u8];

/// Take a checked subrange. Empty ranges are valid, including at the end.
pub fn bytes_sub(bytes: Bytes<'_>, offset: usize, length: usize) -> Option<Bytes<'_>> {
    let end = offset.checked_add(length)?;
    bytes.get(offset..end)
}

/// Take a checked mutable subrange. Empty ranges are valid, including at the end.
pub fn mut_bytes_sub(
    bytes: MutBytes<'_>,
    offset: usize,
    length: usize,
) -> Option<MutBytes<'_>> {
    let end = offset.checked_add(length)?;
    bytes.get_mut(offset..end)
}

/// Compare byte slices, with length mismatch handled before content comparison.
pub fn bytes_equal(left: Bytes<'_>, right: Bytes<'_>) -> bool {
    left == right
}

/// Ask permission for each backing allocation before attempting it.
///
/// This seam supports deterministic failure injection and bounded allocators.
/// It does not allocate memory itself; the arena separately uses Rust's
/// fallible `try_reserve_exact` API. Return `OutOfMemory` to reject an attempt.
pub trait AllocationGate {
    fn permit(&mut self, requested_bytes: usize) -> Result<(), BaseStatus>;
}

#[derive(Default)]
#[doc(hidden)]
pub struct SystemAllocationGate;

impl AllocationGate for SystemAllocationGate {
    fn permit(&mut self, _requested_bytes: usize) -> Result<(), BaseStatus> {
        Ok(())
    }
}

const MAX_ALIGNMENT: usize = 4096;
static NEXT_ARENA_ID: AtomicU64 = AtomicU64::new(1);

// Each element begins on a 4096-byte boundary, sufficient for every supported
// arena alignment. Vec's element layout carries this alignment contract.
#[repr(align(4096))]
struct AlignedBlock([u8; MAX_ALIGNMENT]);

struct Chunk {
    blocks: Vec<AlignedBlock>,
    capacity: usize,
    used: usize,
}

impl Chunk {
    fn try_new(capacity: usize, gate: &mut dyn AllocationGate) -> Result<Self, BaseStatus> {
        let block_count = capacity
            .checked_add(MAX_ALIGNMENT - 1)
            .ok_or(BaseStatus::Overflow)?
            / MAX_ALIGNMENT;
        let allocation_bytes = block_count
            .checked_mul(std::mem::size_of::<AlignedBlock>())
            .ok_or(BaseStatus::Overflow)?;
        gate.permit(allocation_bytes)?;
        let mut blocks = Vec::new();
        blocks
            .try_reserve_exact(block_count)
            .map_err(|_| BaseStatus::OutOfMemory)?;
        blocks.resize_with(block_count, || AlignedBlock([0; MAX_ALIGNMENT]));
        Ok(Self {
            blocks,
            capacity,
            used: 0,
        })
    }

}

/// An opaque allocation identity and byte range within an arena.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ArenaHandle {
    arena_id: u64,
    chunk: usize,
    offset: usize,
    length: usize,
}

impl ArenaHandle {
    /// Length requested for this allocation.
    pub fn len(self) -> usize {
        self.length
    }

    /// Whether this handle describes an empty allocation.
    pub fn is_empty(self) -> bool {
        self.length == 0
    }
}

/// A borrowed, possibly segmented view of one arena allocation.
///
/// Segments arise because safe standard-library storage uses 4096-aligned
/// blocks; no pointer reinterpretation is needed to expose initialized bytes.
pub struct ArenaSlice<'a> {
    blocks: &'a [AlignedBlock],
    offset: usize,
    length: usize,
}

impl ArenaSlice<'_> {
    pub fn len(&self) -> usize { self.length }
    pub fn is_empty(&self) -> bool { self.length == 0 }
    pub fn get(&self, index: usize) -> Option<u8> {
        if index >= self.length { return None; }
        let absolute = self.offset.checked_add(index)?;
        self.blocks.get(absolute / MAX_ALIGNMENT)?.0.get(absolute % MAX_ALIGNMENT).copied()
    }
    pub fn copy_to(&self, destination: &mut [u8]) -> Option<()> {
        if destination.len() != self.length { return None; }
        for (index, byte) in destination.iter_mut().enumerate() { *byte = self.get(index)?; }
        Some(())
    }
}

/// A mutable borrowed, possibly segmented view of one arena allocation.
pub struct ArenaSliceMut<'a> {
    blocks: &'a mut [AlignedBlock],
    offset: usize,
    length: usize,
}

impl ArenaSliceMut<'_> {
    pub fn len(&self) -> usize { self.length }
    pub fn is_empty(&self) -> bool { self.length == 0 }
    pub fn get(&self, index: usize) -> Option<u8> {
        if index >= self.length { return None; }
        let absolute = self.offset.checked_add(index)?;
        self.blocks.get(absolute / MAX_ALIGNMENT)?.0.get(absolute % MAX_ALIGNMENT).copied()
    }
    pub fn set(&mut self, index: usize, value: u8) -> Option<()> {
        if index >= self.length { return None; }
        let absolute = self.offset.checked_add(index)?;
        *self.blocks.get_mut(absolute / MAX_ALIGNMENT)?.0.get_mut(absolute % MAX_ALIGNMENT)? = value;
        Some(())
    }
    pub fn copy_from(&mut self, source: &[u8]) -> Option<()> {
        if source.len() != self.length { return None; }
        for (index, value) in source.iter().copied().enumerate() { self.set(index, value)?; }
        Some(())
    }
}

/// Observable arena accounting, measured in payload bytes.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct ArenaStats {
    pub chunk_count: usize,
    pub payload_capacity: usize,
    pub used_bytes: usize,
}

/// Configuration for bounded arena payload storage.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ArenaConfig {
    pub initial_chunk_bytes: usize,
    pub capacity_limit: usize,
}

/// Reusable bounded storage with stable handles, alignment, and reset behavior.
pub struct Arena<G = SystemAllocationGate> {
    id: u64,
    gate: G,
    chunks: Vec<Chunk>,
    initial_chunk_bytes: usize,
    capacity_limit: usize,
    payload_capacity: usize,
}

impl Arena<SystemAllocationGate> {
    /// Create an arena using fallible standard-library allocations.
    pub fn new(config: ArenaConfig) -> Result<Self, BaseStatus> {
        Self::with_allocation_gate(config, SystemAllocationGate)
    }
}

impl<G: AllocationGate> Arena<G> {
    /// Create an arena with a caller-provided allocation permission seam.
    pub fn with_allocation_gate(config: ArenaConfig, gate: G) -> Result<Self, BaseStatus> {
        if config.initial_chunk_bytes == 0 {
            return Err(BaseStatus::Invalid);
        }
        if config.initial_chunk_bytes > config.capacity_limit {
            return Err(BaseStatus::Limit);
        }
        let id = NEXT_ARENA_ID
            .try_update(Ordering::Relaxed, Ordering::Relaxed, |current| current.checked_add(1))
            .map_err(|_| BaseStatus::Overflow)?;
        Ok(Self {
            id,
            gate,
            chunks: Vec::new(),
            initial_chunk_bytes: config.initial_chunk_bytes,
            capacity_limit: config.capacity_limit,
            payload_capacity: 0,
        })
    }

    /// Reserve `size` bytes with power-of-two alignment up to 4096.
    ///
    /// A zero-sized request succeeds with `None`, matching the C null output.
    /// Any failure leaves arena accounting and existing handles unchanged.
    pub fn push(
        &mut self,
        size: usize,
        alignment: usize,
    ) -> Result<Option<ArenaHandle>, BaseStatus> {
        if alignment == 0 || alignment > MAX_ALIGNMENT || !alignment.is_power_of_two() {
            return Err(BaseStatus::Invalid);
        }
        if size == 0 {
            return Ok(None);
        }

        for (index, chunk) in self.chunks.iter_mut().enumerate() {
            if let Some(offset) = fitting_offset(chunk.used, chunk.capacity, size, alignment) {
                let end = offset.checked_add(size).ok_or(BaseStatus::Overflow)?;
                chunk.used = end;
                return Ok(Some(ArenaHandle {
                    arena_id: self.id,
                    chunk: index,
                    offset,
                    length: size,
                }));
            }
        }
        self.append_chunk(size, alignment).map(Some)
    }

    fn append_chunk(&mut self, size: usize, alignment: usize) -> Result<ArenaHandle, BaseStatus> {
        let remaining = self
            .capacity_limit
            .checked_sub(self.payload_capacity)
            .ok_or(BaseStatus::Overflow)?;
        if size > remaining {
            return Err(BaseStatus::Limit);
        }
        let capacity = self.initial_chunk_bytes.min(remaining).max(size);
        let mut chunk = Chunk::try_new(capacity, &mut self.gate)?;
        let offset = fitting_offset(0, chunk.capacity, size, alignment).ok_or(BaseStatus::Overflow)?;
        let end = offset.checked_add(size).ok_or(BaseStatus::Overflow)?;
        chunk.used = end;
        let new_capacity = self
            .payload_capacity
            .checked_add(capacity)
            .ok_or(BaseStatus::Overflow)?;
        self.chunks
            .try_reserve(1)
            .map_err(|_| BaseStatus::OutOfMemory)?;
        let index = self.chunks.len();
        self.chunks.push(chunk);
        self.payload_capacity = new_capacity;
        Ok(ArenaHandle {
            arena_id: self.id,
            chunk: index,
            offset,
            length: size,
        })
    }

    /// Return a borrowed view of a live handle, or `None` if it is invalid.
    pub fn get(&self, handle: ArenaHandle) -> Option<ArenaSlice<'_>> {
        if handle.arena_id != self.id { return None; }
        let chunk = self.chunks.get(handle.chunk)?;
        let end = handle.offset.checked_add(handle.length)?;
        if end > chunk.capacity { return None; }
        Some(ArenaSlice { blocks: &chunk.blocks, offset: handle.offset, length: handle.length })
    }

    /// Return a mutable borrowed view of a live handle, or `None` if invalid.
    pub fn get_mut(&mut self, handle: ArenaHandle) -> Option<ArenaSliceMut<'_>> {
        if handle.arena_id != self.id { return None; }
        let chunk = self.chunks.get_mut(handle.chunk)?;
        let end = handle.offset.checked_add(handle.length)?;
        if end > chunk.capacity { return None; }
        Some(ArenaSliceMut { blocks: &mut chunk.blocks, offset: handle.offset, length: handle.length })
    }

    /// Check an allocation's alignment. Every chunk base is 4096-byte aligned.
    pub fn handle_is_aligned(&self, handle: ArenaHandle, alignment: usize) -> bool {
        alignment != 0
            && alignment <= MAX_ALIGNMENT
            && alignment.is_power_of_two()
            && self.get(handle).is_some()
            && handle.offset % alignment == 0
    }

    /// Snapshot current payload usage and capacity.
    pub fn stats(&self) -> ArenaStats {
        ArenaStats {
            chunk_count: self.chunks.len(),
            payload_capacity: self.payload_capacity,
            used_bytes: self.chunks.iter().map(|chunk| chunk.used).sum(),
        }
    }

    /// Clear all usage while retaining every allocated chunk for reuse.
    pub fn reset(&mut self) {
        for chunk in &mut self.chunks {
            chunk.used = 0;
        }
    }
}

fn fitting_offset(used: usize, capacity: usize, size: usize, alignment: usize) -> Option<usize> {
    let remainder = used % alignment;
    let padding = if remainder == 0 { 0 } else { alignment - remainder };
    let offset = used.checked_add(padding)?;
    let end = offset.checked_add(size)?;
    (end <= capacity).then_some(offset)
}

use vexel_base::{
    bytes_equal, bytes_sub, mut_bytes_sub, size_add, size_mul, AllocationGate, Arena,
    ArenaConfig, BaseStatus, Span,
};
use std::cell::Cell;
use std::rc::Rc;

#[derive(Clone, Default)]
struct FailingGate(Rc<Cell<(usize, usize)>>);

impl FailingGate {
    fn fail_on(&self, call: usize) {
        let (attempts, _) = self.0.get();
        self.0.set((attempts, call));
    }
    fn fail_next(&self) {
        let (attempts, _) = self.0.get();
        self.0.set((attempts, attempts + 1));
    }
}

impl AllocationGate for FailingGate {
    fn permit(&mut self, _requested_bytes: usize) -> Result<(), BaseStatus> {
        let (attempts, fail_on) = self.0.get();
        let call = attempts + 1;
        self.0.set((call, fail_on));
        if fail_on != 0 && call == fail_on {
            return Err(BaseStatus::OutOfMemory);
        }
        Ok(())
    }
}

fn next_random(state: &mut u64) -> u64 {
    *state ^= *state << 13;
    *state ^= *state >> 7;
    *state ^= *state << 17;
    *state
}

#[test]
fn span_valid_empty_bounds_and_overflow() {
    assert_eq!(Span::from_offset_length(1, 2).and_then(|span| span.slice(b"abcd")), Some(&b"bc"[..]));
    assert_eq!(Span::from_offset_length(4, 0).and_then(|span| span.slice(b"abcd")), Some(&b""[..]));
    assert_eq!(Span { start: 3, end: 2 }.slice(b"abcd"), None);
    assert_eq!(Span { start: 0, end: 5 }.slice(b"abcd"), None);
    assert_eq!(Span::from_offset_length(usize::MAX, 1), None);
}

#[test]
fn arithmetic_matches_original_assertions_and_randomized_cases() {
    assert_eq!(size_add(0, 0), Some(0));
    assert_eq!(size_add(usize::MAX, 0), Some(usize::MAX));
    assert_eq!(size_add(usize::MAX, 1), None);
    assert_eq!(size_mul(0, usize::MAX), Some(0));
    assert_eq!(size_mul(usize::MAX, 1), Some(usize::MAX));
    assert_eq!(size_mul(usize::MAX, 2), None);

    let mut seed = 0x4d59_5df4_d0f3_3173;
    for _ in 0..100_000 {
        let a = next_random(&mut seed) as usize;
        let b = next_random(&mut seed) as usize;
        assert_eq!(size_add(a, b), a.checked_add(b));
        assert_eq!(size_mul(a, b), a.checked_mul(b));
    }
}

#[test]
fn immutable_and_mutable_slices_preserve_original_assertions() {
    let mut bytes = [0u8; 64];
    let mut copy = [0u8; 64];
    for i in 0..bytes.len() {
        bytes[i] = (i * 17) as u8;
        copy[i] = bytes[i];
    }
    assert!(bytes_equal(&bytes, &copy));
    assert!(bytes_equal(&[], &[]));
    assert!(!bytes_equal(&bytes, &copy[..63]));
    copy[7] ^= 1;
    assert!(!bytes_equal(&bytes, &copy));

    let mut seed = 0x9e37_79b9_7f4a_7c15;
    for _ in 0..10_000 {
        let offset = (next_random(&mut seed) as usize) % (bytes.len() + 1);
        let length = (next_random(&mut seed) as usize) % (bytes.len() - offset + 1);
        assert_eq!(bytes_sub(&bytes, offset, length), Some(&bytes[offset..offset + length]));
        let sub = mut_bytes_sub(&mut bytes, offset, length).unwrap();
        assert_eq!(sub.len(), length);
    }
    assert_eq!(bytes_sub(&bytes, usize::MAX, 1), None);
    assert_eq!(bytes_sub(&bytes, 0, usize::MAX), None);
    assert_eq!(bytes_sub(&bytes[..1], 0, 2), None);
    assert_eq!(bytes_sub(&bytes, bytes.len(), 0), Some(&[][..]));
    assert_eq!(mut_bytes_sub(&mut bytes, 65, 0), None);
}

#[test]
fn arena_alignment_reset_stats_and_limit() {
    assert_eq!(Arena::new(ArenaConfig { initial_chunk_bytes: 0, capacity_limit: 8 }).err(), Some(BaseStatus::Invalid));
    let config = ArenaConfig { initial_chunk_bytes: 16, capacity_limit: 96 };
    let mut arena = Arena::new(config).unwrap();
    assert_eq!(arena.stats().chunk_count, 0);
    assert_eq!(arena.stats().payload_capacity, 0);
    assert_eq!(arena.stats().used_bytes, 0);
    assert_eq!(arena.push(0, 4096).unwrap(), None);
    assert_eq!(arena.push(1, 0), Err(BaseStatus::Invalid));
    assert_eq!(arena.push(1, 3), Err(BaseStatus::Invalid));
    assert_eq!(arena.push(1, 8192), Err(BaseStatus::Invalid));

    let mut handles = Vec::new();
    for alignment in [1, 2, 4, 8, 16, 64, 256, 4096] {
        let handle = arena.push(1, alignment).unwrap().unwrap();
        assert!(arena.handle_is_aligned(handle, alignment));
        handles.push(handle);
    }
    let before = arena.stats();
    assert!(before.chunk_count >= 1 && before.payload_capacity <= 96);
    assert!(before.used_bytes <= before.payload_capacity);
    assert_eq!(arena.push(48, 1), Err(BaseStatus::Limit));

    arena.reset();
    let after = arena.stats();
    assert_eq!(after.chunk_count, before.chunk_count);
    assert_eq!(after.payload_capacity, before.payload_capacity);
    assert_eq!(after.used_bytes, 0);
    assert!(arena.push(8, 8).unwrap().is_some());
    assert_eq!(arena.stats().chunk_count, before.chunk_count);
    assert_eq!(Arena::new(ArenaConfig { initial_chunk_bytes: 9, capacity_limit: 8 }).err(), Some(BaseStatus::Limit));
}

#[test]
fn arena_storage_handles_survive_growth_and_support_borrowed_access() {
    let mut arena = Arena::new(ArenaConfig { initial_chunk_bytes: 8, capacity_limit: 64 }).unwrap();
    let first = arena.push(8, 1).unwrap().unwrap();
    arena.get_mut(first).unwrap().copy_from(b"abcdefgh").unwrap();
    let _second = arena.push(8, 1).unwrap().unwrap();
    let mut copied = [0u8; 8];
    arena.get(first).unwrap().copy_to(&mut copied).unwrap();
    assert_eq!(&copied, b"abcdefgh");
    assert_eq!(first, first);
    let other = Arena::new(ArenaConfig { initial_chunk_bytes: 8, capacity_limit: 8 }).unwrap();
    assert!(other.get(first).is_none());
}

#[test]
fn allocator_failure_is_atomic_and_cleanup_is_owned() {
    let gate = FailingGate::default();
    let config = ArenaConfig { initial_chunk_bytes: 8, capacity_limit: 24 };
    gate.fail_on(1);
    let mut arena = Arena::with_allocation_gate(config, gate.clone()).unwrap();
    assert_eq!(arena.push(8, 1), Err(BaseStatus::OutOfMemory));
    assert_eq!(arena.stats().chunk_count, 0);

    gate.fail_on(0);
    let first = arena.push(8, 1).unwrap().unwrap();
    let before = arena.stats();
    // Reject the next chunk. The existing allocation and accounting stay live.
    gate.fail_next();
    assert_eq!(arena.push(8, 1), Err(BaseStatus::OutOfMemory));
    assert_eq!(arena.stats(), before);
    assert_eq!(arena.get(first).unwrap().len(), 8);
    gate.fail_on(0);
    assert!(arena.push(8, 1).unwrap().is_some());
    assert!(arena.push(8, 1).unwrap().is_some());
    assert_eq!(arena.stats().chunk_count, 3);
    assert_eq!(arena.stats().payload_capacity, 24);
    assert_eq!(arena.push(1, 1), Err(BaseStatus::Limit));
}

#[test]
fn arena_reports_overflow_without_partial_state_change() {
    let mut arena = Arena::new(ArenaConfig { initial_chunk_bytes: 1, capacity_limit: usize::MAX }).unwrap();
    let before = arena.stats();
    assert_eq!(arena.push(usize::MAX, 1), Err(BaseStatus::Overflow));
    assert_eq!(arena.stats(), before);
}

//! Bounded, caller-configured work accounting and cancellation.
//!
//! Charges count completed work and are intentionally not rolled back when a
//! caller later rolls back a higher-level source transaction. Callers should
//! charge/checkpoint in batches of at most 256 work units.

use std::sync::atomic::{AtomicBool, Ordering};

/// Categories shared by incremental parsers, renderers, and related workers.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(usize)]
pub enum WorkKind {
    SourceRead,
    TokenVisit,
    ReferenceProbe,
    Transform,
    Expansion,
    Edge,
    PaintVisit,
    ClipChain,
    ClipChild,
    ClipEdge,
    ShapePixel,
    ShapeSample,
    FillEdgeTest,
    FillIntervalTest,
    StrokeTest,
    ScanlineEdgeEntry,
    ShapeRowVisit,
    BoundaryMark,
    FilterPixel,
    AnimationTransform,
    Media,
}

impl WorkKind {
    pub const ALL: [Self; 21] = [
        Self::SourceRead, Self::TokenVisit, Self::ReferenceProbe, Self::Transform,
        Self::Expansion, Self::Edge, Self::PaintVisit, Self::ClipChain, Self::ClipChild,
        Self::ClipEdge, Self::ShapePixel, Self::ShapeSample, Self::FillEdgeTest,
        Self::FillIntervalTest, Self::StrokeTest, Self::ScanlineEdgeEntry,
        Self::ShapeRowVisit, Self::BoundaryMark, Self::FilterPixel,
        Self::AnimationTransform, Self::Media,
    ];

    const fn index(self) -> usize { self as usize }
}

/// The first reason a work-control job stopped.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Stop { Canceled, Limit, Overflow }

/// Error returned by a controlled operation, preserving its original error.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ControlledError<E> {
    Original(E),
    Canceled,
    Limit,
    Overflow,
    OutOfMemory,
}

impl<E> From<Stop> for ControlledError<E> {
    fn from(stop: Stop) -> Self {
        match stop {
            Stop::Canceled => Self::Canceled,
            Stop::Limit => Self::Limit,
            Stop::Overflow => Self::Overflow,
        }
    }
}

/// A real result shape for work performed by a controlled worker.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ControlledStep<T, E> {
    Pending { charged_units: u64 },
    Complete(T),
    Failed(ControlledError<E>),
}

/// Object-safe boundary for bounded work and cancellation checks.
pub trait WorkControl {
    fn charge(&mut self, kind: WorkKind, units: u64) -> Result<(), Stop>;
    fn checkpoint(&mut self) -> Result<(), Stop>;
}

/// Fixed-size per-kind caps. Unconfigured kinds default to `u64::MAX`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WorkLimits([u64; WorkKind::ALL.len()]);

impl WorkLimits {
    /// Create a policy with no per-kind cap below the `u64` counter maximum.
    pub const fn unlimited() -> Self { Self([u64::MAX; WorkKind::ALL.len()]) }

    /// Set one kind's cap, returning the updated fixed-size policy.
    pub const fn with_limit(mut self, kind: WorkKind, limit: u64) -> Self {
        self.0[kind.index()] = limit;
        self
    }

    const fn get(self, kind: WorkKind) -> u64 { self.0[kind.index()] }
}

impl Default for WorkLimits {
    fn default() -> Self { Self::unlimited() }
}

/// Immutable snapshot of successfully accepted work units.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WorkStats {
    total_units: u64,
    per_kind: [u64; WorkKind::ALL.len()],
}

impl WorkStats {
    pub const fn total_units(&self) -> u64 { self.total_units }
    pub const fn units(&self, kind: WorkKind) -> u64 { self.per_kind[kind.index()] }
}

/// Safe budget and cancellation state borrowing the caller's real cancel flag.
pub struct BudgetControl<'a> {
    cancel: &'a AtomicBool,
    total_limit: u64,
    kind_limits: WorkLimits,
    stats: WorkStats,
    stopped: Option<Stop>,
}

impl<'a> BudgetControl<'a> {
    /// Construct with an explicit total limit and unlimited per-kind limits.
    pub const fn new(cancel: &'a AtomicBool, total_limit: u64) -> Self {
        Self::with_limits(cancel, total_limit, WorkLimits::unlimited())
    }

    /// Construct with explicit total and per-kind policies.
    pub const fn with_limits(cancel: &'a AtomicBool, total_limit: u64, kind_limits: WorkLimits) -> Self {
        Self {
            cancel,
            total_limit,
            kind_limits,
            stats: WorkStats { total_units: 0, per_kind: [0; WorkKind::ALL.len()] },
            stopped: None,
        }
    }

    /// Snapshot accepted counters. Failed charges never change this value.
    pub const fn stats(&self) -> WorkStats { self.stats }

    fn stop(&mut self, reason: Stop) -> Stop {
        *self.stopped.get_or_insert(reason)
    }

    fn cancellation_requested(&self) -> bool {
        // Cancellation is a signal only; callers must synchronize unrelated
        // shared data independently. Acquire pairs with conventional Release stores.
        self.cancel.load(Ordering::Acquire)
    }
}

impl WorkControl for BudgetControl<'_> {
    fn charge(&mut self, kind: WorkKind, units: u64) -> Result<(), Stop> {
        if let Some(stop) = self.stopped { return Err(stop); }
        if self.cancellation_requested() { return Err(self.stop(Stop::Canceled)); }

        let Some(total) = self.stats.total_units.checked_add(units) else {
            return Err(self.stop(Stop::Overflow));
        };
        let current_kind = self.stats.per_kind[kind.index()];
        let Some(per_kind) = current_kind.checked_add(units) else {
            return Err(self.stop(Stop::Overflow));
        };
        if total > self.total_limit || per_kind > self.kind_limits.get(kind) {
            return Err(self.stop(Stop::Limit));
        }
        self.stats.total_units = total;
        self.stats.per_kind[kind.index()] = per_kind;
        Ok(())
    }

    fn checkpoint(&mut self) -> Result<(), Stop> {
        if let Some(stop) = self.stopped { return Err(stop); }
        if self.cancellation_requested() { return Err(self.stop(Stop::Canceled)); }
        Ok(())
    }
}

use std::sync::atomic::{AtomicBool, Ordering};
